import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader oquvchi = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(oquvchi.readLine().trim());
        int olcham = 1;
        while (olcham < n) olcham *= 2;
        long[] t = new long[2 * olcham];
        StringTokenizer st = new StringTokenizer(oquvchi.readLine());
        for (int i = 0; i < n; i++) t[olcham + i] = Long.parseLong(st.nextToken());
        for (int i = olcham - 1; i >= 1; i--) t[i] = t[2 * i] + t[2 * i + 1];

        int q = Integer.parseInt(oquvchi.readLine().trim());
        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < q; k++) {
            st = new StringTokenizer(oquvchi.readLine());
            String buyruq = st.nextToken();
            int x = Integer.parseInt(st.nextToken());
            int y = Integer.parseInt(st.nextToken());
            if (buyruq.equals("set")) {
                int i = olcham + x - 1;
                t[i] = y;
                i /= 2;
                t[i] = t[2 * i] + t[2 * i + 1];
            } else {
                int l = olcham + x - 1, r = olcham + y;
                long jam = 0;
                while (l < r) {
                    if (l % 2 == 1) jam += t[l++];
                    if (r % 2 == 1) jam += t[--r];
                    l /= 2;
                    r /= 2;
                }
                sb.append(jam).append('\n');
            }
        }
        System.out.print(sb);
    }
}

